                PLB                             ; ...and straight off: DBR = the
                                                ;   callee.  NET ZERO, which is
                                                ;   why it can follow the copy.
                REP     #$30
                MX      %00
                PHK                             ; upret_ufs_sbvalid is in OUR bank
                PEA     upret_ufs_sbvalid-1
                PHB                             ; target bank: DBR is the callee's
                                                ;   now, and PHB is exactly the
                                                ;   one byte RTL wants
                TXA
                DEC     A
                PHA                             ; target - 1
                RTL                             ; PILECALL
upret_ufs_sbvalid TAY                             ; park the return value; the stack
                                                ;   fix needs the register
                TSC
                CLC
                ADC     #8
                TCS
                TYA
                PHK
                PLB                             ; DBR ours again, recovered from
                                                ;   PB rather than saved
                RTL

